package com.dentalclinic.consultation;
import com.dentalclinic.casesheet.dto.*;
import com.dentalclinic.casesheet.entity.TreatmentPlanRequirement;
import com.dentalclinic.casesheet.service.EntryException;
import com.dentalclinic.consultation.entity.ConsultationStatus;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="CONSULTATION_LIFECYCLE_TEST_DATABASE",matches="true")
class TreatmentDecisionDatabaseTest extends ConsultationLifecycleDatabaseTest {
 void decision(TreatmentPlanRequirement value,String reason){var r=text("Pain");r.setTreatmentPlanRequirement(value);r.setTreatmentDecisionReason(reason);sheets.updateCaseSheet(parent,clinic,r,token());}
 UUID plan(String status,boolean item){var id=UUID.randomUUID();jdbc.update("insert into treatment_plan(id,clinic_id,patient_id,doctor_id,case_sheet_id,consultation_id,appointment_id,treatment_plan_number,status) values (?,?,?,?,?,?,?,?,?)",id,clinic,patient,doctor,parent,consultation,appointment,id.toString(),status);if(item){var procedure=UUID.randomUUID();jdbc.update("insert into procedure_master(id,clinic_id,procedure_code,procedure_name) values (?,?,?,'Test')",procedure,clinic,procedure.toString());jdbc.update("insert into treatment_plan_item(clinic_id,treatment_plan_id,procedure_id,procedure_code_snapshot,procedure_name_snapshot) values (?,?,?,'TEST','Test')",clinic,id,procedure);}return id;}
 @Test void missingDecisionDraftAllowedFinalizationBlocked(){decision(null,null);diagnosis();assertNull(sheets.getCaseSheet(parent,clinic).getTreatmentPlanRequirement());assertEquals(409,assertThrows(EntryException.class,this::finalizeSheet).status);}
 @Test void requiredRejectsMissingEmptyDraftCancelledRemovedAndUnrelated(){decision(TreatmentPlanRequirement.REQUIRED,null);diagnosis();assertThrows(EntryException.class,this::finalizeSheet);plan("DRAFT",true);plan("CANCELLED",true);plan("PRESENTED",false);var other=plan("PRESENTED",true);jdbc.update("update treatment_plan set case_sheet_id=null where id=?",other);var removed=plan("PRESENTED",true);jdbc.update("update treatment_plan set removed_at=current_timestamp,removed_by=? where id=?",user,removed);assertThrows(EntryException.class,this::finalizeSheet);assertEquals("DRAFT",sheets.getCaseSheet(parent,clinic).getStatus().name());}
 @Test void requiredEvidenceSurvivesLaterCancellation(){decision(TreatmentPlanRequirement.REQUIRED,null);diagnosis();var p=plan("PRESENTED",true);finalizeSheet();jdbc.update("update treatment_plan set status='CANCELLED' where id=?",p);change(ConsultationStatus.IN_PROGRESS);change(ConsultationStatus.COMPLETED);assertEquals("PRESENTED",jdbc.queryForObject("select treatment_plan_status from case_sheet_treatment_finalization where case_sheet_id=?",String.class,parent));assertThrows(Exception.class,()->jdbc.update("delete from case_sheet_treatment_finalization where case_sheet_id=?",parent));}
 @Test void noPlanRequiredAndDeferredComplete(){decision(TreatmentPlanRequirement.DEFERRED,"Awaiting diagnostic results");diagnosis();finalizeSheet();change(ConsultationStatus.IN_PROGRESS);change(ConsultationStatus.COMPLETED);assertEquals("Awaiting diagnostic results",jdbc.queryForObject("select reason from case_sheet_treatment_finalization where case_sheet_id=?",String.class,parent));}
 @Test void deferredReasonRequiredAndVersionsPreserved(){var version=token();assertEquals(400,assertThrows(EntryException.class,()->decision(TreatmentPlanRequirement.DEFERRED,"\u2003 ")).status);assertEquals(version,token());decision(TreatmentPlanRequirement.NOT_REQUIRED,null);assertNotEquals(version,token());assertEquals(412,assertThrows(EntryException.class,()->sheets.updateCaseSheet(parent,clinic,text("Other"),version)).status);}
 @Test void legacyFinalizedRemainsCompletable(){jdbc.update("update case_sheet set status='FINALIZED',treatment_plan_requirement=null where id=?",parent);change(ConsultationStatus.IN_PROGRESS);change(ConsultationStatus.COMPLETED);assertNull(sheets.getCaseSheet(parent,clinic).getTreatmentPlanRequirement());}
 @Test void decisionRollbackAndFinalizationEvidenceAtomic(){diagnosis();assertThrows(IllegalStateException.class,()->new TransactionTemplate(transactions).executeWithoutResult(tx->{finalizeSheet();throw new IllegalStateException();}));assertEquals("DRAFT",sheets.getCaseSheet(parent,clinic).getStatus().name());assertEquals(0,jdbc.queryForObject("select count(*) from case_sheet_treatment_finalization where case_sheet_id=?",Integer.class,parent));}
 @Test void decisionEditBeforeFinalizationRejectsStaleReview()throws Exception{diagnosis();var v=token();race(()->decision(TreatmentPlanRequirement.DEFERRED,"Await results"),()->finalizeVersion(v),412);}
 @Test void cancellationBeforeFinalizationIsAuthoritative()throws Exception{decision(TreatmentPlanRequirement.REQUIRED,null);diagnosis();var p=plan("PRESENTED",true);race(()->jdbc.update("update treatment_plan set status='CANCELLED' where id=?",p),this::finalizeSheet,409);}
 @Test void finalizedDecisionCannotBeEdited(){diagnosis();finalizeSheet();assertThrows(IllegalArgumentException.class,()->decision(TreatmentPlanRequirement.DEFERRED,"Too late"));}

 @org.junit.jupiter.params.ParameterizedTest
 @org.junit.jupiter.params.provider.ValueSource(strings={"PRESENTED","APPROVED","IN_PROGRESS","COMPLETED","DECLINED"})
 void documentedStatusesQualifyWithoutPatientAcceptance(String status){decision(TreatmentPlanRequirement.REQUIRED,null);diagnosis();plan(status,true);finalizeSheet();assertEquals(status,jdbc.queryForObject("select treatment_plan_status from case_sheet_treatment_finalization where case_sheet_id=?",String.class,parent));}
 @Test void noPlanNeededWhenExplicitlyNotRequired(){decision(TreatmentPlanRequirement.NOT_REQUIRED,"Consultation only");diagnosis();finalizeSheet();change(ConsultationStatus.IN_PROGRESS);change(ConsultationStatus.COMPLETED);assertEquals(1,jdbc.queryForObject("select count(*) from case_sheet_treatment_finalization where case_sheet_id=? and treatment_plan_id is null",Integer.class,parent));}
 @Test void finalizationBeforePlanCancellationKeepsEvidence()throws Exception{decision(TreatmentPlanRequirement.REQUIRED,null);diagnosis();var p=plan("PRESENTED",true);race(this::finalizeSheet,()->jdbc.update("update treatment_plan set status='CANCELLED' where id=?",p),200);assertEquals("PRESENTED",jdbc.queryForObject("select treatment_plan_status from case_sheet_treatment_finalization where case_sheet_id=?",String.class,parent));change(ConsultationStatus.IN_PROGRESS);change(ConsultationStatus.COMPLETED);}
 @Test void cancelledItemsDoNotQualify(){decision(TreatmentPlanRequirement.REQUIRED,null);diagnosis();var p=plan("PRESENTED",true);jdbc.update("update treatment_plan_item set status='CANCELLED' where treatment_plan_id=?",p);assertEquals(409,assertThrows(EntryException.class,this::finalizeSheet).status);}
 @Test void missingFinalizationEvidenceCannotBypassCompletion(){decision(TreatmentPlanRequirement.REQUIRED,null);jdbc.update("update case_sheet set status='FINALIZED' where id=?",parent);change(ConsultationStatus.IN_PROGRESS);assertEquals(409,assertThrows(EntryException.class,()->change(ConsultationStatus.COMPLETED)).status);}
}
